package com.alex.universalshieldapi.api; import net.minecraft.core.registries.Registries; import net.minecraft.resources.Identifier; import net.minecraft.tags.TagKey; import net.minecraft.world.item.Item; import net.minecraft.world.item.ItemStack; import java.util.*; import java.util.concurrent.*; public final class UniversalShieldApi { public static final TagKey<Item> SHIELDS=TagKey.create(Registries.ITEM,Identifier.fromNamespaceAndPath("universal-shield-api","shields")); private static final Set<Item> ITEMS=ConcurrentHashMap.newKeySet(); private static final List<ShieldHandler> HANDLERS=new CopyOnWriteArrayList<>(); private static final Map<ShieldHookType,List<ShieldHook>> HOOKS=new EnumMap<>(ShieldHookType.class); static{for(var t:ShieldHookType.values())HOOKS.put(t,new CopyOnWriteArrayList<>());} private UniversalShieldApi(){} public static void registerShield(Item i){ITEMS.add(Objects.requireNonNull(i));} public static boolean unregisterShield(Item i){return ITEMS.remove(i);} public static boolean isShield(ItemStack s){return s.is(SHIELDS)||ITEMS.contains(s.getItem());} public static Set<Item> registeredItems(){return Set.copyOf(ITEMS);} public static void registerHandler(ShieldHandler h){HANDLERS.add(Objects.requireNonNull(h));} public static boolean unregisterHandler(ShieldHandler h){return HANDLERS.remove(h);} public static void registerHook(ShieldHookType t,ShieldHook h){HOOKS.get(t).add(Objects.requireNonNull(h));} public static boolean unregisterHook(ShieldHookType t,ShieldHook h){return HOOKS.get(t).remove(h);} public static ShieldActionResult fireHook(ShieldHookType t,ShieldContext c,ShieldActionResult r){for(var h:HOOKS.get(t)){r=h.apply(c,r);if(r==ShieldActionResult.FAIL)break;}return r;} public static ShieldActionResult invoke(ShieldContext c){var r=fireHook(ShieldHookType.BEFORE_HANDLER,c,ShieldActionResult.PASS);if(r!=ShieldActionResult.PASS)return r;for(var h:HANDLERS){r=h.handle(c);if(r!=ShieldActionResult.PASS)break;}return fireHook(ShieldHookType.AFTER_HANDLER,c,r);} }